package com.paa.checks;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.stream.Stream;

public final class PaaChecks {
    private static final String COMMIT = "9565154901e57f184bfdd3cef5f23dd4014e2c03";
    private static final List<String> CONTRACTS = List.of("specs/openapi/gateway-api.yaml", "specs/openapi/gateway-engine.yaml", "specs/openapi/model-api.yaml", "specs/schemas/configuration.json", "specs/schemas/identity.json", "specs/schemas/message.json", "specs/schemas/policy.json", "specs/schemas/tool-definition.json");
    private PaaChecks() {}
    public static void main(String[] args) { Path source = null; for (int index = 0; index < args.length - 1; index++) if (args[index].equals("--source-checkout")) source = Path.of(args[index + 1]); List<String> errors = run(Path.of("."), source); if (errors.isEmpty()) System.out.println("Java PAA checks passed."); else { System.err.println("Java PAA checks failed:"); errors.forEach(error -> System.err.println("- " + error)); System.exit(1); } }
    public static List<String> run(Path root, Path source) { List<String> errors = new ArrayList<>(); errors.addAll(checkContracts(root, source)); errors.addAll(checkBoundaries(root)); errors.addAll(checkRequiredFiles(root)); return errors; }
    private static List<String> checkContracts(Path root, Path source) {
        List<String> errors = new ArrayList<>(); String lock = read(root.resolve("paa.lock.json")); if (!lock.contains("\"repository\": \"https://github.com/Personal-AI-Architecture/the-architecture.git\"") || !lock.contains("\"ref\": \"main\"") || !lock.contains("\"source_root\": \"vendor/paa-contracts\"")) errors.add("paa.lock.json does not describe the expected PAA repository, ref, and source root."); if (!lock.contains("\"commit\": \"" + COMMIT + "\"")) errors.add("paa.lock.json must pin the expected PAA commit.");
        for (String relative : CONTRACTS) { Path vendor = root.resolve("vendor/paa-contracts").resolve(relative), mirror = root.resolve(relative); if (!Files.isRegularFile(vendor)) { errors.add("Missing vendored contract: " + relative); continue; } String actual = sha256(vendor); if (!lock.contains("\"" + relative + "\": \"" + actual + "\"")) errors.add("Hash drift in vendored contract: " + relative); if (!same(vendor, mirror)) errors.add("Local contract mirror differs from vendored source: " + relative); if (source != null && !java.util.Arrays.equals(sourceBytes(source, relative), readBytes(vendor))) errors.add("Vendored contract differs from " + COMMIT + ":" + relative); }
        String gateway = read(root.resolve("specs/openapi/gateway-api.yaml")), engine = read(root.resolve("specs/openapi/gateway-engine.yaml")), model = read(root.resolve("specs/openapi/model-api.yaml")); for (String route : List.of("  /conversations/messages:", "  /conversations:", "  /conversations/{id}:", "  /conversations/{id}/messages:")) if (!gateway.contains(route)) errors.add("Gateway API path is missing: " + route); for (String marker : List.of("SendMessageRequest", "ConversationList", "Conversation", "ClientSSEStream")) if (!gateway.contains(marker)) errors.add("Gateway schema is missing: " + marker); for (String marker : List.of("/engine/chat:", "EngineRequest:", "RequestMetadata:", "SSEStream:", "X-Actor-ID", "X-Actor-Permissions")) if (!engine.contains(marker)) errors.add("Gateway-Agent Loop contract is missing: " + marker); for (String marker : List.of("/completions:", "CompletionRequest:", "CompletionStream:")) if (!model.contains(marker)) errors.add("Model API contract is missing: " + marker); return errors;
    }
    private static List<String> checkBoundaries(Path root) { List<String> errors = new ArrayList<>(); Path source = root.resolve("src/main/java/com/paa"); try (Stream<Path> files = Files.walk(source)) { files.filter(Files::isRegularFile).filter(path -> List.of("config", "engine", "gateway", "memory", "types").stream().anyMatch(component -> path.toString().contains("/" + component + "/"))).forEach(path -> { String text = read(path); for (String token : List.of("/chat/completions", "apiBaseUrl", "apiKey", "openai-compatible")) if (text.contains(token)) errors.add("Provider-specific token " + token + " must stay within adapters/: " + path); }); } catch (IOException error) { errors.add("Unable to inspect Java boundaries: " + error.getMessage()); } String metadata = read(source.resolve("types/EngineRequestMetadata.java")); for (String forbidden : List.of("providerAdapter", "model", "tools")) if (metadata.contains(forbidden)) errors.add("EngineRequestMetadata contains runtime reconfiguration key: " + forbidden); String gateway = read(source.resolve("gateway/Gateway.java")); for (String marker : List.of("/conversations/messages", "/conversations", "/messages")) if (!gateway.contains(marker)) errors.add("Gateway runtime is missing route marker: " + marker); return errors; }
    private static List<String> checkRequiredFiles(Path root) { return Stream.of("src/main/java/com/paa/types/ModelAdapter.java", "src/main/java/com/paa/adapters/AdapterLoader.java", "src/main/java/com/paa/adapters/MockAdapter.java", "src/main/java/com/paa/adapters/OpenAiCompatibleAdapter.java", "src/main/java/com/paa/engine/AgentLoop.java", "src/main/java/com/paa/gateway/Gateway.java", "src/main/java/com/paa/memory/MemoryStore.java").filter(relative -> !Files.isRegularFile(root.resolve(relative))).map(relative -> "Missing required file: " + relative).toList(); }
    private static String read(Path path) { try { return Files.readString(path); } catch (IOException error) { return ""; } }
    private static byte[] readBytes(Path path) { try { return Files.readAllBytes(path); } catch (IOException error) { return new byte[0]; } }
    private static boolean same(Path left, Path right) { return java.util.Arrays.equals(readBytes(left), readBytes(right)); }
    private static String sha256(Path path) { try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path))); } catch (Exception error) { return ""; } }
    private static byte[] sourceBytes(Path source, String relative) { try { Process process = new ProcessBuilder("git", "-C", source.toString(), "show", COMMIT + ":" + relative).start(); byte[] bytes = process.getInputStream().readAllBytes(); process.waitFor(); return process.exitValue() == 0 ? bytes : new byte[0]; } catch (Exception error) { return new byte[0]; } }
}
